sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
          /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
          /* Optional GlideRecord */ event) {

          // Add your code here

	if (current.raised_for.manager)
    email.addAddress("cc", current.raised_for.user.manager.email);

	if (current.assignment_group.manager)
    email.addAddress("cc", current.assignment_group.manager.email);

	if (current.raised_for)
    email.addAddress("cc", current.raised_for.user.email);

})(current, template, email, email_action, event);
